  ('39425dc8-d374-422c-bf23-8d49ae2adc5d', '846f5851-e482-47a6-a76d-7d66c760d9d5', $$aflossing lening, gelijkmatige veranderingen, interestkosten € 29.000; IVV 2%$$,
